formulas.expression:
IF(
    AND(
       OR(
           {!Mailing_Street_Person} <> {!Get_Selected_Member.PersonMailingStreet},
           {!Mailing_City_Person} <> {!Get_Selected_Member.PersonMailingCity},
           {!Mailing_State_Person_PL} <> TEXT({!Get_Selected_Member.PersonMailingStateCode}),
           {!Mailing_Zip_Postal_Code_Person} <> {!Get_Selected_Member.PersonMailingPostalCode} 
       ),
    {!Mailing_Physical_Addresses_Same_Person} == false
    ),
    true,
    false
)
